#ifndef _ION_KE_IO_DEVICE_H
#define _ION_KE_IO_DEVICE_H 1

#include <ion/base.h>
#include <ion/list.h>

struct _BUS_OBJECT;
struct _DRIVER_OBJECT;

#define IO_DEVICE_AUTOGENERATED_NAME            0x00000001

typedef enum _DEVICE_TYPE {
    DeviceBeep,
    DeviceOther,
} DEVICE_TYPE;

typedef struct _DEVICE_OBJECT {
    ULONG Flags;
    DEVICE_TYPE Type;

    struct _DRIVER_OBJECT *Driver;
    LIST_ENTRY DriverEntry;

    struct _BUS_OBJECT *Bus;
    LIST_ENTRY BusEntry;

    SIZE_T IrpStackSize;

    VOID *DeviceExtension;
} DEVICE_OBJECT;

#endif
